import{_ as e,o as a,c as o,Q as i}from"./chunks/framework.77ba20c6.js";const q=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Mi Intestino en Órbita","text":"Centro de Control para Guerreros Invisibles","tagline":"Deja de adivinar. Empieza a registrar. Toma el control de tu EII con ciencia y datos.","actions":[{"theme":"brand","text":"📊 Empieza a registrar","link":"/tablero"},{"theme":"alt","text":"🔬 Lee la Guerra Invisible","link":"/guerra-invisible"}]},"features":[{"icon":"📊","title":"El Panel de Control","details":"Registra tus síntomas, deposiciones, sueño y estrés en un solo lugar. Visualiza tu evolución y detecta patrones."},{"icon":"🔬","title":"Ciencia Traducida","details":"Estudios médicos explicados en cristiano. Sin filtros, sin medias verdades. Para que llegues a la consulta con argumentos."},{"icon":"🎯","title":"Visibilidad Real","details":"Herramientas para explicar lo que sientes a tu médico y a tu familia. La EII es invisible, pero tú no tienes por qué serlo."},{"icon":"🛡️","title":"Comunidad de Guerreros","details":"No estás solo. Conoce a otros pacientes, comparte experiencias y aprende de los que ya han pasado por lo que tú estás viviendo."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),t={name:"index.md"},s=i('<div class="custom-manifesto"><h2 id="¿por-que-cree-esto" tabindex="-1">¿Por qué creé esto? <a class="header-anchor" href="#¿por-que-cree-esto" aria-label="Permalink to &quot;¿Por qué creé esto?&quot;">​</a></h2><p><strong>Hace 5 años me diagnosticaron EII. Y durante 5 años, mi vida fue un caos.</strong></p><p>Médicos que me decían que mis análisis estaban bien mientras yo no podía levantarme de la cama. Familiares que no entendían por qué no podía ir a la cena de Navidad. Y una enfermedad invisible que nadie veía, pero que yo sentía cada segundo.</p><p>Hasta que decidí tomar el control. Empecé a registrar mis síntomas, a leer estudios, a entender mi cuerpo y a aprender a comunicar lo que sentía.</p><p>Esta web es el resultado de ese viaje. No hay recetas mágicas ni dietas milagro. Solo herramientas reales: un calendario de síntomas, estudios traducidos, preguntas para tu médico y una comunidad para que no te sientas solo.</p><p><strong>Porque llevar un intestino invisible no tiene por qué ser una guerra en solitario.</strong></p><p>Bienvenido a tu centro de control.</p><p>— Loli</p></div>',1),n=[s];function r(d,l,c,u,p,m){return a(),o("div",null,n)}const v=e(t,[["render",r]]);export{q as __pageData,v as default};
